import{_ as p}from"./chunks/a0305120e644b85ed6d4.Un8bzcJN.js";import{_ as o,C as r,o as i,c as n,j as t,a as l,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"为什么选择细分领域是愚蠢的（致聪明人）","description":"","frontmatter":{"title":"为什么选择细分领域是愚蠢的（致聪明人）","originalTitle":"Why Choosing A Niche Is Stupid (For Intelligent People)","date":"2022-04-22","originalUrl":"https://thedankoe.com/letters/why-choosing-a-niche-is-stupid-for-intelligent-people/","minutes":11,"sourceHash":"e1414bded7b809e030ba795430063a029c27b4663c14c3dcbefbf714e13477b0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-choosing-a-niche-is-stupid-for-intelligent-people/"}]]},"headers":[],"relativePath":"letters/why-choosing-a-niche-is-stupid-for-intelligent-people.md","filePath":"letters/why-choosing-a-niche-is-stupid-for-intelligent-people.md"}'),c={name:"letters/why-choosing-a-niche-is-stupid-for-intelligent-people.md"};function d(m,e,f,b,u,g){const a=r("ArticleMeta");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"为什么选择细分领域是愚蠢的-致聪明人",tabindex:"-1"},[l("为什么选择细分领域是愚蠢的（致聪明人） "),t("a",{class:"header-anchor",href:"#为什么选择细分领域是愚蠢的-致聪明人","aria-label":'Permalink to "为什么选择细分领域是愚蠢的（致聪明人）"'},"​")],-1)),s(a),e[1]||(e[1]=h('<p>人类每秒可以处理126比特的信息（根据我的研究，谷歌的说法不同，哎，不管了）。这在我们的一生中（平均而言）加起来多达1850亿比特的信息。这些比特的信息储存在我们大脑的某个地方。通过意识，我们将这些信息排序。也就是说，我们意识到的东西会被储存下来。我们意识到的是我们将注意力集中的事物。是我们专注的事物。这其中还有更多门道，但关键在于，我们在这一生中能够意识到的信息量是有限的。</p><p>我认为这是人类潜能的一个关键因素——就算不是人类潜能的主要衡量标准。虽然大多数人将15%的意识注意力放在淋浴、洗澡、打理自己、做饭和其他必需品上——但大多数人也会瘫躺着，看电视，刷表情包，用无用的活动麻痹自己的头脑。把他们的潜能付之东流。</p><p><a href="https://www.modernmastery.co/post/how-to-not-end-up-mediocre" target="_blank" rel="noreferrer">上周我们讨论了肯·威尔伯（Ken Wilber）的全子理论</a>。探讨了我们作为人类，必须在特定领域发展自己，并经历3个发展阶段——让我们在该领域的技能成为艺术。肯提到过这一点，但上面的统计数据证实了它。人类可以通过意识发展处理1850亿比特的信息。这限制了我们能够真正发展自己的领域数量。这也意味着其他人同样受到相同的限制。每个人都会在生活的不同领域发展自己——按照许多哲学家和古代导师的说法，这就是带来幸福的东西。不这么做则会带来不幸。</p><p>也就是说，拥有一个愿景、一个目标，并有意识地努力去实现这些事情，这才是奏效的方法——“在过程中寻找乐趣。”</p><p>尼采曾说：</p><blockquote><p><em>“幸福就是力量增加的感觉——是阻力被克服的感觉。”</em></p></blockquote><p>米哈里·契克森米哈赖（Csikszentmihalyi）曾说：</p><blockquote><p><em>“一个能控制意识的人的标志，在于能够随心所欲地集中注意力，对干扰视而不见，能够为了达成目标而持续专注足够长的时间，且不多花一分精力。而能做到这一点的人，通常也很享受日常的平凡生活。”</em></p></blockquote><p>如果我们把这放在游戏的语境下考虑——比如《魔兽世界》——你会在达到满级时停滞。你能获得的经验值是有限的。你在技能树的特定特性上能分配的“点数”也是有限的。如果你不玩剧情或不参与游戏的各个部分，你就无法达到满级（或发挥最大潜能）。如果你把点数分散得太散，与那些明智分配点数的人相比，你最终拥有的力量将微乎其微。</p><p>心态、专注、整理你的思绪、避免分心，以及其他意味着利用你有限的意识来发展觉察力并追求基于兴趣的层级目标的说法，是全面享受生活的主钥匙之一。</p><p>这本身就是一个课题，我会在未来的信中讨论。你永远无法进入另一个人的精神状态。你永远无法理解他们是如何控制自己意识的。你永远不会理解他们正在追求并能为他们带来幸福的目标层级。仅仅因为某人不去举铁、不创业、不改善健康，不去做我谈论的所有这些事情——并不意味着他们不是由衷地感到幸福。一个顺着多巴胺的诱导在纯素饮食的兔子洞中深入探索的人，可能因为他们有序的意识而比我更幸福。评判是无用的。假设是无用的。期望是无用的。做对你来说最好的事，让别人做对他们最好的事。只有当别人想要被触及时才去教导。“智慧的嘴唇是紧闭的，除非遇到理解的耳朵。”</p><p>如果我们想进一步探讨，我未来书中的三大支柱是专注、能量和体验。在我眼中，专注就是有意识的注意力。无论你信不信，能量存在于你周围的每一件事物中。无论是积极的还是消极的。你关注什么，就会为你“倾注”注意力的事物注入生命和能量。这种能量反射到你身上，主宰你的体验。根据契克森米哈赖的说法，体验是基于你意识到的事物所储存的信息。这种体验将构成未来一切事物的基础。</p><p>我扯远了……</p><h2 id="创作者-经济如何加速我们的发展" tabindex="-1">“创作者”经济如何加速我们的发展 <a class="header-anchor" href="#创作者-经济如何加速我们的发展" aria-label="Permalink to &quot;“创作者”经济如何加速我们的发展&quot;">​</a></h2><p>几天前的晚上，我和 JK Molina 聊天，我们讨论了在商业发展中对创造力的需求。可以这样想……通过特定的知识——即课程、教练指导、学徒制以及其他形式的在线教育——人们正在将大约10年的信息、经验和失败打包并简化为在生活特定领域取得成功的简单可行路线图。书籍、文章、视频、播客等等。<a href="https://open.spotify.com/episode/5DdgoAufTrFF6tzd4B6zXy?si=9b98ded372ce4bf8" target="_blank" rel="noreferrer">消费它们，但要有一个项目来将这些想法联系起来，并激发模式识别。</a></p><p>你可以说这些信息被浓缩或压缩了。如果你愿意，可以称之为一个 zip 压缩包。我们的大脑现在能够以快得多的速度处理过去需要10年的信息。这些信息不再占据我们大约50亿比特的意识注意力，而是只占据约1000万比特。这意味着我们正在“创造”解决问题的方案，突破个人在生活和职业发展中的极限，并为他们做同样的事情腾出空间。</p><p>我花了5年时间才在自由职业中取得成功。在我将一切打包成我的第一本电子书并出售后——其他人几个月内就取得了成功。现在，他们可以在更短的时间内取得更大的成功，将他们1-3年的学习成果打包，并传授下去。这导致了特定领域的指数级发展。同时也允许在多个领域快速发展。计算机编程过去是一门极其高度专业化的领域。现在有了各种框架、教育资源和学习方法，能让你在没有学位的情况下，在6个月内找到一份高薪的网络开发工作。这种趋势只会继续加速——特别是对于科技领域的人和那些敢于从事创造性工作的人来说。</p><p>我的观点是，我们正在压缩需要处理的信息量。多亏了创作者和科技，我们能比前人学到更多。我们不需要在某个特定领域死磕。事实上，专攻一件事是在极大地限制我们自己。一个人通过专业化变得有价值，而通过成为一个现代文艺复兴式全才变得不可替代。通过加强他们的专业知识，并通过学习互补领域来为创造力腾出空间。一个独立创业者能够蓬勃发展，因为他们可以学习营销、销售、一门有市场的技能、邮件营销、创作内容、剪辑视频、投放广告、打造产品、获取线索等。在你作为创作者的一生中，通过压缩、系统化和产品化这个过程——作为一人企业，你可以赚到100万到500万美元。当然，一个小团队能增加更多的火力。</p><p>你看到成为创作者的力量和必要性了吗？在做你热爱的事情的同时，你确确实实地在“提升人类的集体意识”。通过创造新颖的解决方案，快速提升个人在特定领域的发展。同时由于教学相长，你自己的发展也会得到更大的提升。如果你不断生产/创造内容、产品、服务和简化的理解方式，你就为进一步的创新腾出了空间。</p><p>附注：说实话，我对这篇时事通讯具有多么大的创造性“融合”感到惊讶。如果不成为一个创作者，我就无法建立这些联系，而这正是我的观点。你必须经历那些发展阶段，利用现有的特定知识（自我教育），并成为一名创作者，通过价值生产来进一步增强、连接和简化这些知识。</p><h2 id="专业化是一个伪神" tabindex="-1">专业化是一个伪神 <a class="header-anchor" href="#专业化是一个伪神" aria-label="Permalink to &quot;专业化是一个伪神&quot;">​</a></h2><p>还记得上周我们是如何讨论前/超谬误（pre-trans fallacy）的吗？从前理性、理性到超理性的发展阶段？本质上，这个模因对生活的方方面面不都是如此吗？</p><p><img src="'+p+'" alt=""></p><p>细分领域智商钟形曲线</p><p>“万事通”或文艺复兴式的全才在过去能给人带来成功。接着是专业化时代。现在，对于那些看到机会并抓住它的人来说，文艺复兴时代正在回归——主要是在网络世界。</p><p>让我问你一个问题。我的细分领域是什么？我的专业是什么？你能给我一个明确的答案吗？如果你告诉我“在线业务”或“自我提升”或“哲学与灵性”甚至“健身与健康”，我都不会同意。我的个人品牌是我选择发展自己的那些领域的一个综合体——一种相互关联的状态。我的细分领域是“以上所有”，这是创造力的前奏。不限制自己，让我能与那些在类似领域发展自己的人建立联系。不限制自己，为模式识别腾出了空间，让我能把各种点连起来，对任何给定的话题带来全新的、新颖的视角。它让我自己和我的产品能从同质化商品的汪洋大海中脱颖而出。</p><p>当然，专业化在起步阶段很重要，而且在长期来看也非常有用。这就是变得有价值和变得不可替代之间的区别。样样稀松的万金油 VS 精通“一门”的多面手。在专攻一个领域的同时，利用现代创新让你在多个领域快速发展自己，这会给你带来<em>杠杆</em>。你在子领域的发展只会帮助你更有效地发展你的主领域。</p><h2 id="现代商业的体验模型" tabindex="-1">现代商业的体验模型 <a class="header-anchor" href="#现代商业的体验模型" aria-label="Permalink to &quot;现代商业的体验模型&quot;">​</a></h2><p>世界正在发生转变。随着科技的进步，我们正慢慢变得更加像人（如果你明智地利用它）。它为更多的创意追求以及借此赚取巨额收入的能力腾出了空间。</p><p>于是，这就引出了我的“体验模型”理念，旨在让你在创作者/注意力经济中蓬勃发展。</p><p>你一生中处理的信息量决定了你的条件反射、心智程序、信仰、偏见、认知、身份、个性、技能水平以及其余的一切。你的注意力放在哪里（或如何被操纵）决定了你的体验。你的体验将成为你创作的基础。也就是你的内容、产品和服务。你的潜能将成为你的品牌。也就是你的愿景、目标和价值观。没有人能复制这个“细分领域”，你也不受限于你所创造的产品。只要你懂得<a href="https://www.modernmastery.co/post/learn-these-skills-if-you-want-to-thrive-in-2022" target="_blank" rel="noreferrer">长青技能</a>，它们就会是赚钱的。</p><p>你看到这一切是如何形成闭环的了吗？个人成长 = 商业成长。</p><p>在内容创作方面，有一件事值得思考：你是否能通过新奇的事物吸引人们的注意力，让他们意识到自己想要追求的具体兴趣，用紧凑而有价值的信息填满他们有限的意识，从而引导他们走向更好的生活？最重要的是，这就是个人品牌或创作者的关键所在。</p><p>你塑造自己的愿景、目标和价值观——为之努力，并吸引追随者，将他们引向这种更美好的生活。你的愿景是你和追随者渴望得到的结果。你的目标是你正在努力的方向。你的价值观是你和追随者正在发展自我的领域。所有这些构成了你的内容支柱。当到了创作内容的时候，你依靠的是你的经验。随着你在这些领域不断提升自我，你吸取的经验教训会变得越来越有创意。在开辟实现愿景的道路上，你通过自己的错误、见解和成功来传授知识。这是一份极具成就感的工作。人们追随你，是因为你是引导他们走向更好生活的、自信而真实的领导者。</p><p>创造力随之而来。我们如何将其融入生活和业务中，以实现最大、最快的进步？答案是：在已经创造出的理念和特定知识的基础之上进行构建。当你追随并效仿其他领导者或令人向往的榜样时，你就能让自己的愿景变得清晰。就像那句俗话说的，“每一个优秀的教练都有自己的教练。”</p><p>顺便提醒一下，这更像是一种哲学视角的探讨——如果你想获取我简单直接的商业、社交媒体和绩效系统，作为创作者建立一个数十万美元收益的业务，<a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">请在这里加入 MMHQ</a>。</p><h2 id="如何顺应自然地生活-与赚钱" tabindex="-1">如何顺应自然地生活（与赚钱） <a class="header-anchor" href="#如何顺应自然地生活-与赚钱" aria-label="Permalink to &quot;如何顺应自然地生活（与赚钱）&quot;">​</a></h2><p>第一步是觉知。觉知你所受的条件反射和程序化设定。假以时日，你的心智会敞开。你会恢复到孩子般的状态……或者我应该说，你超越了成人的状态（前超谬误），并解锁了自信、好奇心和创造力的天赋。</p><p>通过好奇心，你追求那些你真正感兴趣的发展领域。你通过模式识别和多巴胺积累动能。你开始建立来自不同领域的连接——而且，除非你升华成为创作者（孩子 = 创作者，成年人 = 消费者，充满童心的成年人 = 创作者），否则你无法在这些领域充分发展自己。如果你不教导、不领导、不去做那些必要的事情，你就无法到达下一个发展阶段。</p><p>通过顺应自然（你的直觉）去追求你的兴趣，你就能成为一个“一人细分领域”。你建立起自己品牌的“个人垄断”。你的生活顺应了互联网的进化（自然）。你与宇宙的整体发展一同流转（并从中获利）。这本就是你应该做的。你之所以没有意识到这一点，是因为你与自己的存在（being）脱节了——并且你没有一个成为（becoming）的锚点。</p><p>你<em>选择</em>如何填补那 1850 亿比特信息的方式，将与他人截然不同。当然，你们会共享一些相似之处，但此时竞争已经无关紧要了。你的“细分领域”是你一生中储存的数十亿比特信息的具象化显现。简而言之，你能分享的东西比你想象的要多——你只需要一个与在线增长相关的目标层级，在品牌、营销和销售方面自我教育，并保持动能。</p><p>这比你想象的要容易。阻碍你前进的唯一障碍就是你自己。是你对头脑的无意识认同。你的内在已经拥有了一切——你需要做的就是拥抱你与生俱来的好奇心，让它成为你的向导，传承你的经验，并通过内容、产品和服务来记录这段旅程。</p><p>当然，这里还有更多的技术细节，但我已经制作了数百篇关于这些内容的时事通讯、<a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">MMHQ 文章</a>、播客、课程、视频、培训和帖子。你需要的一切都已经存在于互联网上了。你之所以对它们视而不见，是因为你任由干扰物夺走并占据了你的注意力。</p><p>醒醒吧。</p><p>Dan Koe</p><hr><p><a href="/en/letters/why-choosing-a-niche-is-stupid-for-intelligent-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',47))])}const w=o(c,[["render",d]]);export{y as __pageData,w as default};
